], { 'dy.daily': DEF_DAILY, 'dy.hot': DEF_HOT });
const DAY = 24 * 3600e3;
const dailies = () => (D.daily = (D.daily || []).filter(d => Date.now() - d.at < DAY || d.keep || G.charOf(d.by)).slice(-200));   // TA 的过期日常不在抖音里显示，但留给记忆总览
