const dailySeen = w => dailyOf(w).every(d => (d.views || []).includes('me'));
function dailyRow() {
    if (!dailyOn()) return '';
    const ws = Array.from(new Set(liveDaily().filter(d => d.by !== 'me').sort((a, b) => b.at - a.at).map(d => d.by))).sort((a, b) => dailySeen(a) - dailySeen(b));
    const mine = dailyOf('me');
