}
let DV = null;   // { w, i }
Y.dailyView = (w, i) => { const L = dailyOf(w); if (!L.length) return; DV = { w, i: i || Math.max(0, L.findIndex(d => !(d.views || []).includes('me'))) }; G.push(APP, { id: 'daily', title: '', cls: 'dy-dvb', html: () => dailyHtml() }); };
