    const L = dailyOf(DV.w); const d = L[DV.i]; if (!d) return '<div class="dy-empty">没有了</div>';
    d.views = d.views || []; if (!d.views.includes('me') && DV.w !== 'me') { d.views.push('me'); saveD(); }
